import logo from './logo.svg';
import './App.css';
import { Hub, About, Leaderboard } from './Home.js';
import axios from 'axios';

import { BrowserRouter, Routes, Route, Link } from 'react-router-dom';

function getUserId() {
    let user_id = 0;

    axios.get('/api/user_id')
        .then(response => {
            console.log(response);
            user_id = response.user_id;
        })
        .catch(err => {
            console.error('Error:', err);
        });

    return user_id;
}

function NavigationButton({ path, title, color }) {
    const navigate = useNavigate();

    const handleClick = () => {
        navigate(path);
    };

    return (
        <button 
            onClick={handleClick}
            style={{ backgroundColor: color, color: 'white', padding: '10px 20px', margin: '5px' }}
        >
            {title}
        </button>
    );
}

export default function App() {

    const user_id = getUserId()

    return (
        <BrowserRouter>
            <NavigationButton
                title = "Play"
                color = "#1a3caa"
                path = "/hub"
            />

            <NavigationButton
                title = "Leaderboard"
                color = "#1a9c2a"
                path = "/leaderboard"
            />

            <NavigationButton
                title = "About"
                color = "#aa3c3a"
                path = "/about"
            />
          {/* Routes */}
          <Routes>
            <Route path="/hub" element={<Hub />} />
            <Route path="/about" element={<About />} />
            <Route path="/leaderboard" element={<Leaderboard />} />
          </Routes>
        </BrowserRouter>
    );
}
